package br.com.archlab.api;
import br.com.archlab.api.v3.*;import br.com.archlab.simulation.core.v3.*;import org.junit.jupiter.params.ParameterizedTest;import org.junit.jupiter.params.provider.ValueSource;import tools.jackson.databind.json.JsonMapper;import java.nio.file.*;import static org.junit.jupiter.api.Assertions.*;
class GoldenResultsV3Test {
    private final JsonMapper json=JsonMapper.builder().build();
    @ParameterizedTest @ValueSource(strings={"ce-ref-01","horizon-150","simulated-failure"})
    void matchesVersionedGoldenWithoutUpdatingExpectedValues(String name) throws Exception {String input=Files.readString(Path.of("../../docs/examples/v3/ce-ref-01-request.json"));if(name.equals("horizon-150"))input=input.replace("\"completionMode\": \"DRAIN_ALL\"","\"completionMode\":\"UNTIL_HORIZON\",\"horizonAtMs\":150");if(name.equals("simulated-failure"))input=input.replace("\"initialStates\": []","\"initialStates\": [{\"kind\":\"COMPONENT\",\"componentId\":\"db\",\"available\":false}]");var request=new SimulationRequestMapperV3().map(json.readTree(input));var engine=new SimulationEngineV3(request);engine.run();var actual=json.readTree(json.writeValueAsString(new SimulationResponseMapperV3().map(ResultProjectorV3.project(engine.checkpoint()))));var expected=json.readTree(Files.readString(Path.of("../../docs/examples/v3/golden-results.json"))).get(name);
        assertEquals(expected.get("integrity"),actual.get("integrity"),"Snapshot, trace and entire result hashes must match golden");assertEquals(expected.get("principalStatus"),actual.at("/principal/status"));assertEquals(expected.get("globalStatus"),actual.at("/global/status"));assertEquals(expected.get("observedUntilMs"),actual.at("/global/observedUntilMs"));assertEquals(expected.get("principalResponseDurationMs"),actual.at("/principal/responseDurationMs"));assertEquals(expected.get("timelineCount").intValue(),actual.get("timeline").size());assertEquals(expected.get("traceCount"),actual.at("/trace/recordCount"));
    }
}
